"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import "./plus-menu.css";

export type PlusMenuItem = { label: string; hint?: string; icon: ReactNode; onSelect: () => void };

/* Plus to menu morph: the + grows into the menu it opens. Anchored at its
   bottom-right corner, so it opens up and to the left. Put it wherever the
   + should sit; it sizes the open menu from the number of items. */
export default function PlusMenu({ items, label = "Add" }: { items: PlusMenuItem[]; label?: string }) {
  const [open, setOpen] = useState(false);
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: PointerEvent) => {
      if (box.current && !box.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("pointerdown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <>
      <div className={"ob-plus-scrim" + (open ? " is-on" : "")} aria-hidden="true" />
      <div className="ob-plus" ref={box} style={{ "--ob-plus-items": items.length } as CSSProperties}>
        <div className="t-morph" data-open={open}>
          <div className="t-morph-menu" role="menu" aria-hidden={!open}>
            {items.map((it) => (
              <button
                key={it.label}
                type="button"
                role="menuitem"
                className="ob-plus-item"
                tabIndex={open ? 0 : -1}
                onClick={() => {
                  setOpen(false);
                  it.onSelect();
                }}
              >
                <span className="ob-plus-icon">{it.icon}</span>
                <span className="ob-plus-text">
                  <span>{it.label}</span>
                  {it.hint && <span className="ob-plus-hint">{it.hint}</span>}
                </span>
              </button>
            ))}
          </div>
          <button
            type="button"
            className="t-morph-plus"
            aria-expanded={open}
            aria-label={label}
            onClick={() => setOpen((o) => !o)}
          >
            <svg width="22" height="22" viewBox="0 0 22 22" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M11 4v14M4 11h14" />
            </svg>
          </button>
        </div>
      </div>
    </>
  );
}

/* Plus menu: transitions.dev's plus-to-menu morph, sized for a thumb. The
   open height follows the item count. */

.ob-plus {
  --ob-plus-size: 58px;
  --ob-plus-width: 264px;
  --ob-plus-row: 58px;
  position: relative; z-index: 2; width: var(--ob-plus-size); height: var(--ob-plus-size); flex: none; pointer-events: auto;
}
.ob-plus .t-morph {
  --morph-r-closed: calc(var(--ob-plus-size) / 2); --morph-r-open: 26px;
  position: absolute; right: 0; bottom: 0; width: var(--ob-plus-size); height: var(--ob-plus-size);
  background: var(--ds-color-text); color: var(--ds-color-bg);
  box-shadow: var(--ob-shadow-float, var(--ds-shadow-lg));
}
.ob-plus .t-morph[data-open="true"] {
  width: var(--ob-plus-width);
  height: calc(16px + var(--ob-plus-items) * (var(--ob-plus-row) + 2px));
}
.ob-plus .t-morph-plus { width: var(--ob-plus-size); height: var(--ob-plus-size); color: inherit; border: 0; background: none; padding: 0; }
.ob-plus .t-morph-menu {
  inset: auto 0 0 auto; width: var(--ob-plus-width);
  height: calc(16px + var(--ob-plus-items) * (var(--ob-plus-row) + 2px));
  padding: 8px; display: grid; align-content: start; gap: 2px;
}
.ob-plus-item {
  display: flex; align-items: center; gap: 12px; width: 100%; height: var(--ob-plus-row); padding: 0 10px;
  border: 0; background: none; font: inherit; cursor: pointer;
  border-radius: 18px; text-align: left; color: inherit;
}
.ob-plus-item:hover, .ob-plus-item:focus-visible { background: color-mix(in srgb, var(--ds-color-bg) 12%, transparent); outline: none; }
.ob-plus-icon { width: 38px; height: 38px; border-radius: 12px; background: color-mix(in srgb, var(--ds-color-bg) 14%, transparent); display: grid; place-items: center; flex: none; }
.ob-plus-text { display: grid; font-weight: 600; font-size: 15px; line-height: 1.25; }
.ob-plus-hint { font-size: 12.5px; font-weight: 500; opacity: 0.6; }
.ob-plus-scrim {
  position: fixed; inset: 0; z-index: 0; background: rgba(10, 10, 8, 0.28);
  opacity: 0; pointer-events: none;
  transition: opacity var(--morph-close-dur) var(--morph-close-ease);
}
.ob-plus-scrim.is-on { opacity: 1; pointer-events: auto; transition-duration: var(--morph-open-dur); }
@media (prefers-reduced-motion: reduce) { .ob-plus-scrim { transition: none; } }
